import{_ as l,a0 as o,w as p,s as d,I as t,x as i,a1 as e,A as a,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"关闭 WSL 中正在运行的 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"关闭 WSL 中正在运行的 Linux 发行版 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"关闭 WSL 中正在运行的 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"关闭 WSL 中正在运行的 Linux 发行版 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20240124 Shut Down WSL Running Linux Distributions","title":"关闭 WSL 中正在运行的 Linux 发行版","tag":"202401","desc":""},"relativePath":"202401/20240124 Shut Down WSL Running Linux Distributions.md","filePath":"[post].md"}'),r={name:"202401/20240124 Shut Down WSL Running Linux Distributions.md"};function h(g,s,b,k,x,L){const n=o("Link");return p(),d("div",null,[s[18]||(s[18]=t("h1",{id:"关闭-wsl-中正在运行的-linux-发行版",tabindex:"-1"},[i("关闭 WSL 中正在运行的 Linux 发行版 "),t("a",{class:"header-anchor",href:"#关闭-wsl-中正在运行的-linux-发行版","aria-label":"Permalink to “关闭 WSL 中正在运行的 Linux 发行版”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202401/31/111542n7hb9b97xd56dpth.jpg",alt:""})],-1)),s[20]||(s[20]=t("blockquote",null,[t("p",null,"以下是使用 WSL 关闭在 Windows 内运行的 Linux 系统的不同方法。")],-1)),s[21]||(s[21]=t("p",null,"你使用 WSL 在 Windows 内运行 Linux 吗？你想知道如何关闭在 WSL 中运行的 Linux 发行版吗？",-1)),t("p",null,[s[1]||(s[1]=i("你当然可以在 WSL 中运行的 Linux 系统中 ",-1)),e(n,{href:"https://linuxhandbook.com/linux-shutdown-command/"},{default:a(()=>[...s[0]||(s[0]=[i("执行 shutdown 命令",-1)])]),_:1}),s[2]||(s[2]=i("：",-1))]),s[22]||(s[22]=u(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo shutdown now</span></span></code></pre></div><p>你还可以使用 <code>wsl</code> 命令关闭 Linux 系统。如果你有多个发行版在 WSL 中运行，这是一种极好的方法。</p><h3 id="在-wsl-中使用-windows-终端关闭-linux-系统" tabindex="-1">在 WSL 中使用 Windows 终端关闭 Linux 系统 <a class="header-anchor" href="#在-wsl-中使用-windows-终端关闭-linux-系统" aria-label="Permalink to “在 WSL 中使用 Windows 终端关闭 Linux 系统”">​</a></h3><p>在这个方法中，我假设通常的 <code>shutdown</code> 命令在 WSL Linux 系统中不起作用。</p><p>首先，在 Windows 中打开一个终端。在这里，我使用的是 Windows 11，并在 WSL 2 下安装了 Ubuntu。</p><p><img src="https://itsfoss.com/content/images/2024/01/open-a-terminal-from-start-menu.png" alt="打开 Windows 终端"></p><blockquote><p>💡 你可以在标准的 Windows 终端上使用 <code>wsl</code> 命令。在运行的 Linux 发行版中也可以访问该命令。这里，命令的名称是 <code>wsl.exe</code>。</p></blockquote><p>现在，你需要列出已安装的发行版及其状态。为此，请输入</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --list --verbose</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>wsl -l -v</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/list-installed-distributions-and-their-status.png" alt="列出已安装的发行版"></p><p>在这里，你可以看到，我已经安装了一个 WSL Ubuntu，它目前正在运行。</p><h4 id="关闭所有正在运行的-linux-发行版" tabindex="-1">关闭所有正在运行的 Linux 发行版 <a class="header-anchor" href="#关闭所有正在运行的-linux-发行版" aria-label="Permalink to “关闭所有正在运行的 Linux 发行版”">​</a></h4><p>有时，你可能想一次性停止正在运行的 WSL 实例。</p><p>在 Powershell 或 Windows 终端中，使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --shutdown</span></span></code></pre></div><p>这将关闭所有会话。</p><p>此外，你还可以<strong>在任何正在运行的 WSL Linux 发行版终端中执行相同的功能</strong>。在发行版中时，你只需要使用 <code>wsl.exe</code> 而不是 <code>wsl</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe --shutdown</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/shutdown-all-wsl-distros-within-another-distro.gif" alt="关闭所有正在运行的 WSL 发行版"></p><p>运行此命令后，所有正在运行的 WSL 发行版都将终止。WSL 2 轻量级虚拟机也被终止。<strong>因此，如果你想重新启动 WSL 2 虚拟机环境，它将很有用。</strong></p><h4 id="终止特定的-linux-发行版" tabindex="-1">终止特定的 Linux 发行版 <a class="header-anchor" href="#终止特定的-linux-发行版" aria-label="Permalink to “终止特定的 Linux 发行版”">​</a></h4><p>要终止特定正在运行的 WSL 发行版，请打开单独的 Windows 终端并运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --terminate &lt;发行版名称&gt;</span></span></code></pre></div><p>此处，发行版名称是你使用 <code>wsl -l -v</code> ⁣ 命令列出所有已安装的 WSL 发行版时获得的名称。</p><p><img src="https://itsfoss.com/content/images/2024/01/list-the-distro-to-terminate-only-that-one.png" alt="列出 WSL 发行版"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --terminate Ubuntu</span></span></code></pre></div><p>执行后，指定的 Linux 发行版将被终止。</p><p>如果你在另一个发行版中，请使用以下命令列出系统上安装的所有 WSL 发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe -l -v</span></span></code></pre></div><p>现在，使用以下命令终止所需的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe --terminate &lt;发行版名称&gt;</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/shutdown-successfully-completed.png" alt="从另一个 WSL 发行版中关闭 WSL 发行版"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>有些人直接关闭正在运行的 Linux 应用，但我认为这不太优雅。</p><p>另外，就像 Linux 终端一样，你可以使用：</p><ul><li><code>logout</code> 命令，用于关闭该发行版。</li><li><code>exit</code> 命令用于退出运行 Linux 发行版的终端。</li><li>或者，按 <code>CTRL+D</code> 执行与 <code>exit</code> 命令相同的操作。</li></ul><p>但关闭 Linux 系统的 WSL 方式还有一个额外的优势，即可以针对多个 Linux 系统执行此操作。</p><p>我希望它对你有帮助。</p><p><em>（题图：DA/615fd564-a02c-4340-9c8f-ebabcc7c0e0c）</em></p><hr>`,40)),t("p",null,[s[4]||(s[4]=i("via: ",-1)),e(n,{href:"https://itsfoss.com/shut-down-wsl-distros/"},{default:a(()=>[...s[3]||(s[3]=[i("https://itsfoss.com/shut-down-wsl-distros/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),e(n,{href:"https://itsfoss.com/author/sreenath/"},{default:a(()=>[...s[5]||(s[5]=[i("Sreenath",-1)])]),_:1}),s[10]||(s[10]=i(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:a(()=>[...s[7]||(s[7]=[i("geekpi",-1)])]),_:1}),s[12]||(s[12]=i(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中国",-1)])]),_:1}),s[17]||(s[17]=i(" 荣誉推出",-1))])])}const w=l(r,[["render",h]]);export{f as __pageData,w as default};
